/* Original REI landing composition. Existing learning and project routes remain intact. */
window.REIDreamHome=()=>{
 const arrow='<span aria-hidden="true">↗</span>';
 const C=window.REILearningPathCore, saved=window.REILearningStore.readPath();
 const has=Object.values(saved.fields).some(value=>value.trim()), resume=has?saved.last:0;
 const startLabel=has?'Continue my learning':'Start learning';
 const stepDescriptions=['Notice a problem and question your first explanation.','Turn an interest into a feasible research question.','Search deliberately and investigate source credibility.','Compare findings, methods and unanswered questions.','Connect your objective, framework, methods and ethics.','Review your reasoning, seek feedback and plan a revision.'];
 return `<div class="dream-home"><section class="dream-hero" aria-labelledby="dream-title"><div class="dream-hero-meta"><span><i></i> AN INDEPENDENT SPACE FOR CURIOUS MINDS</span><span>RESEARCH, CONNECTED. / 01</span></div><div class="dream-hero-copy"><h1 id="dream-title" aria-label="Curiosity. In a new dimension."><span>Curiosity.</span><span class="dream-outline">In a new</span><span>dimension.</span></h1><div class="dream-intro"><p>Build on the workshop, or begin here on your own. Learn the research process, practice your reasoning and develop a blueprint you can keep improving.</p><a class="button dream-cta" href="#learn/${resume}">${startLabel} ${arrow}</a><div class="dream-lens-controls" aria-label="3D magnifying glass controls"><button type="button" data-lens-action="rotate">Rotate ↻</button><button type="button" data-lens-action="inspect" aria-pressed="false">Inspect +</button><button type="button" data-lens-action="reset">Reset</button></div></div></div><div class="dream-art" data-dream-scene aria-hidden="true"><div class="dream-fallback"><i></i><i></i><i></i></div><canvas></canvas><div class="dream-art-coordinate">LENS 001 / CONNECTING IDEAS</div></div><div class="dream-hero-bottom"><button class="dream-scroll" type="button" data-dream-scroll="home-start"><span class="dream-scroll-line" aria-hidden="true"></span>FIND YOUR STARTING POINT</button><span>YOUR IDEAS. YOUR EVIDENCE. YOUR NEXT CHAPTER.</span><span class="dream-live"><i></i> MADE FOR EXPLORATION</span></div></section><section class="home-start home-flow-intro" id="home-start" aria-labelledby="home-start-title"><h2 id="home-start-title">One path.<br>One step at a time.</h2><p>Begin with the guided lessons. Each step follows the same routine: understand an idea, write about your question, then practice and revise. Your notes stay together in your workbook.</p><ol class="home-flow-overview"><li><strong>1. Learn the process</strong><span>Build your research blueprint in six small steps.</span></li><li><strong>2. Strengthen a skill</strong><span>Return to practice when you need another example.</span></li><li><strong>3. Apply it to your project</strong><span>Work with real sources when you are ready.</span></li></ol><p class="home-section-note">New here? Use Start learning above. Returning? The same button takes you back to your last edited step. You can browse the three parts below without opening every tool.</p></section><section class="dream-manifesto home-roadmap home-category" id="dream-manifesto" aria-labelledby="home-roadmap-title"><span class="home-category-number" aria-hidden="true">01</span><h2 id="home-roadmap-title">Learn the process.</h2><p class="home-section-intro">This is your main route through REI. Follow the workshop sequence from a first observation to a preliminary research blueprint. No seminar attendance is required.</p><div class="home-routine"><strong>Inside every step</strong><p>Read → write → practice → revise → continue.</p><p>Your guide recommends the next activity, so you do not have to choose from the whole library.</p></div><details class="home-deeper home-curriculum"><summary>Preview the six learning steps</summary><ol class="home-step-list">${C.steps.map((step,i)=>`<li><span class="home-step-number">${String(i+1).padStart(2,'0')}</span><div><h3>${step.short}</h3><p>${stepDescriptions[i]}</p></div></li>`).join('')}</ol><p>The step selector inside the guide lets you return to any part.</p></details></section><section class="dream-tools home-practice home-category" aria-labelledby="home-practice-title"><span class="home-category-number" aria-hidden="true">02</span><div class="dream-tools-layout"><div><h2 id="home-practice-title">Strengthen a skill.</h2><p class="home-section-intro">Your guided steps already include practice. Come here when you want extra work on a specific skill, or a fresh example to revisit later.</p><a class="dream-text-link" href="#practice">Open the practice library ${arrow}</a></div><div class="home-category-notes"><h3>Practice has a purpose.</h3><p>Question design and source checking.</p><p>Comparing studies and bounding claims.</p><p>Matching methods, seeking feedback and revising.</p><p>Try first, compare with guidance, then explain what you changed.</p></div></div></section><section class="dream-tools home-apply home-category" aria-labelledby="home-apply-title"><span class="home-category-number" aria-hidden="true">03</span><div class="dream-tools-layout"><div><h2 id="home-apply-title">Apply it to your project.</h2><p class="home-section-intro">Have a question and sources to investigate? Move into the research studio to organize papers, connect evidence and develop your proposal.</p><a class="dream-text-link" href="#research">Open the research studio ${arrow}</a></div><div class="home-category-notes"><h3>Follow the evidence.</h3><ol><li>Keep source details and reading notes.</li><li>Compare findings and their limitations.</li><li>Connect the question, method and argument.</li></ol><p>Your project records are separate from your learning workbook. Nothing transfers automatically.</p></div></div><details class="home-deeper"><summary>Resources and saved work</summary><div class="home-resource-groups"><section><h3>Learning support</h3><a href="#academy">Detailed lessons ${arrow}</a><a href="#toolkit">Templates and checklists ${arrow}</a><a href="#seminars">Additional workshops ${arrow}</a><a href="#learning-evidence">Research behind the activities ${arrow}</a></section><section><h3>Your writing</h3><a href="#workbook">Learning workbook ${arrow}</a><a href="#notebook">Idea notebook ${arrow}</a><a href="#notebook/draft">Full lesson drafts ${arrow}</a><a href="#backup">Backup and recovery ${arrow}</a></section></div></details></section><section class="dream-finale"><h2 data-dream-reveal>A little progress.<br><span class="dream-silver">Something to build on.</span></h2><p>You do not need to open everything today. Follow one guided step, keep your notes and return when you are ready. My workbook is always available in the header.</p><p>Your work stays on this device. No account required.</p><div class="dream-finale-word" aria-hidden="true">rei</div></section></div>`;
};
